// Input 26 masks, then forbidden edges as lo hi. Select an edit before running expensive panel DFS when the optimistic core has few unavoidable sevens. Partition covers both values. Tie branch by footprint on original blue sevens including any newly impossible edits.
#[path="ramsey26_release_tree.rs"]mod rt;use std::io::{self,BufRead};fn tree(a:&mut Vec<u32>,ed:&[(usize,usize)],st:&mut[usize;5]){st[0]+=1;let mut b=a.clone();let mut es:Vec<_>=ed.iter().copied().filter(|&(i,j)|a[i]&a[j]==0).collect();for &(i,j) in &es{b[i]|=1<<j;b[j]|=1<<i}let mut n7=0;for s in rt::sets(&b){if s.count_ones()==8{st[1]+=1;return}if s.count_ones()==7{n7+=1}}if n7>=60||es.is_empty(){if !rt::strong(a,&b){st[2]+=1;return}}else{st[3]+=1}if es.is_empty(){st[4]+=1;println!("{}",a.iter().map(|v|v.to_string()).collect::<Vec<_>>().join(" "));return}let impact=|&(i,j):&(usize,usize)|{let mut t=0;for &(x,y) in &es{if (i==x&&a[j]>>y&1!=0)||(i==y&&a[j]>>x&1!=0)||(j==x&&a[i]>>y&1!=0)||(j==y&&a[i]>>x&1!=0){t+=1}}t};let k=(0..es.len()).max_by_key(|&i|impact(&es[i])).unwrap();let(i,j)=es.swap_remove(k);tree(a,&es,st);a[i]|=1<<j;a[j]|=1<<i;tree(a,&es,st);a[i]^=1<<j;a[j]^=1<<i}fn main(){for l in io::stdin().lock().lines(){let mut a:Vec<u32>=l.unwrap().split_whitespace().map(|v|v.parse().unwrap()).collect();let mut bans=vec![];while a.len()>26{let i=a.pop().unwrap()as usize;let j=a.pop().unwrap()as usize;bans.push((i,j))}let mut ed=vec![];for i in 0..26{for j in 0..i{if a[i]>>j&1==0&&a[i]&a[j]==0&&!bans.contains(&(i,j)){ed.push((i,j))}}}let mut st=[0;5];tree(&mut a,&ed,&mut st);eprintln!("{:?}",st)}}
